}
.login-card h3 {
 font-family: var(--font-head); font-weight: 800; color: var(--navy);
 text-align: center; margin-bottom: 6px;
}
.login-card p.sub {
 font-family: var(--font-body); font-size: .85rem; color: var(--gray-mid);
